	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['invoice', 'challan', 'eway-bill', 'pod', 'other']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['invoice', 'challan', 'eway-bill', 'pod', 'other', 'lr'])) THEN
		RAISE EXCEPTION 'migration 0119: the widened document-kind vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch', 'client-shipment-document', 'client-documents-needed']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch', 'client-shipment-document', 'client-documents-needed', 'client-delivery-update'])) THEN
		RAISE EXCEPTION 'migration 0119: the widened template vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['client-receipt', 'client-dispatch', 'client-shipment-document', 'client-documents-needed']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['client-receipt', 'client-dispatch', 'client-shipment-document', 'client-documents-needed', 'client-delivery-update'])) THEN
		RAISE EXCEPTION 'migration 0119: the widened client-template vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['receipt.recorded', 'order.dispatched', 'shipment.documents', 'consignment.documents-needed']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['receipt.recorded', 'order.dispatched', 'shipment.documents', 'consignment.documents-needed', 'delivery.recorded'])) THEN
		RAISE EXCEPTION 'migration 0119: the widened email-event vocabulary lost a member.';
