	IF EXISTS (SELECT 1 FROM unnest(ARRAY['receipt.recorded', 'order.dispatched']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['receipt.recorded', 'order.dispatched', 'order.delivered'])) THEN
		RAISE EXCEPTION 'migration 0119: the widened webhook event vocabulary lost a member.';
	END IF;
END $$;
