-- ── the post-migration assertion (the 0117/0118 model, A7) ───────────────
-- Made-up uuids. One valid base row per table; each shape merges an override
-- over it (with `disp` merged first where the shape is a departed one). The
-- accepted shapes are inserted and rolled back by a sentinel, so a CHECK that
-- refused everything fails the migration; each refused shape runs in its own
-- subtransaction and must be refused BY ITS NAMED CONSTRAINT (CHECKs run in
-- name order, guide §3: each probe violates only its target). The staff-only
-- RLS is NOT probed here (a migration runs as the owner — RLS is inert); it is
-- proved as `wms_rls_probe` in test/freight-dispatch-migration.spec.ts.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	base jsonb;
	disp jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'code', 'LD-0001', 'status', 'open', 'mode', 'ltl',
		'transporter_partner_id', NULL, 'transporter_snapshot', NULL, 'transporter_name', 'VRL Logistics',
		'vehicle_type', NULL, 'vehicle_number', NULL, 'container_number', NULL, 'vehicle_capacity_kg', NULL, 'vehicle_reported_at', NULL,
		'driver_name', NULL, 'driver_phone', NULL, 'driver_licence_number', NULL, 'dock_door', 'D-3', 'seals', '[]'::jsonb,
		'loading_started_at', NULL, 'dispatched_at', NULL, 'dispatched_by', NULL, 'dispatch_source', NULL, 'dispatch_device_id', NULL,
		'dispatched_order_count', NULL, 'package_count', NULL, 'gross_weight_grams', NULL, 'warehouse_snapshot', NULL,
		'eway_part_b_confirmed_at', NULL, 'eway_part_b_confirmed_by', NULL, 'capacity_exceeded', false,
		'cancelled_at', NULL, 'cancelled_by', NULL, 'cancel_reason', NULL, 'note', NULL, 'created_by', u,
		'created_at', now(), 'updated_at', now());
	disp := jsonb_build_object(
		'status', 'dispatched', 'vehicle_type', 'hcv', 'vehicle_number', 'KA01AB1234', 'driver_name', 'Ravi',
		'seals', '["S-991","S-992"]'::jsonb, 'loading_started_at', '2026-10-30T08:00:00Z', 'dispatched_at', '2026-10-30T10:00:00Z',
		'dispatched_by', u, 'dispatch_source', 'web', 'dispatched_order_count', 2, 'package_count', 21,
		'gross_weight_grams', 9840000, 'warehouse_snapshot', '{"v":1,"code":"BLR1"}'::jsonb);
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('an open load with a typed transporter and no vehicle', false, '{}'),
			('an open load of a transporter partner, FTL, full vehicle', false, '{"mode":"ftl","transporter_partner_id":"%R%","transporter_snapshot":{"v":1,"name":"VRL"},"vehicle_type":"container-40","vehicle_number":"KA01AB1234","container_number":"MSCU1234567","vehicle_capacity_kg":60000,"driver_name":"Ravi","driver_phone":"+919800000000","driver_licence_number":"KA0120190001234"}'),
			('a dispatched web load', true, '{}'),
			('a dispatched handheld load with seals, Part B and over capacity', true, '{"dispatch_source":"handheld","dispatch_device_id":"%R%","seals":["S-1","S-2","S-3","S-4","S-5"],"eway_part_b_confirmed_at":"2026-10-30T10:00:00Z","eway_part_b_confirmed_by":"%U%","capacity_exceeded":true,"gross_weight_grams":20000000000,"package_count":20000,"dispatched_order_count":100}'),
			('a cancelled load', false, '{"status":"cancelled","cancelled_at":"2026-10-30T10:00:00Z","cancelled_by":"%U%","cancel_reason":"Truck did not report"}'),
			('a departure that dispatched nothing (A50)', false, '{"status":"cancelled","cancelled_at":"2026-10-30T10:00:00Z","cancelled_by":"%U%","cancel_reason":"Departed with no dispatchable order","vehicle_number":"KA01AB1234","driver_name":"Ravi","seals":["S-1"]}')
		) AS s(name, departed, override) LOOP
			rec := base || CASE WHEN shape.departed THEN disp ELSE '{}'::jsonb END
				|| jsonb_build_object('id', gen_random_uuid(), 'code', 'LD-' || lpad((floor(random() * 99999999) + 1)::bigint::text, 8, '0'))
				|| replace(replace(shape.override, '%U%', u::text), '%R%', gen_random_uuid()::text)::jsonb;
			INSERT INTO "freight_loads" SELECT (jsonb_populate_record(NULL::"freight_loads", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0119: an accepted load shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0119' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('status closed', 'freight_loads_status_check', false, '{"status":"closed"}'),
		('code LD-1', 'freight_loads_code_shape', false, '{"code":"LD-1"}'),
		('mode part', 'freight_loads_mode_check', false, '{"mode":"part"}'),
		('a partner without its snapshot', 'freight_loads_transporter_pairing', false, '{"transporter_partner_id":"%R%"}'),
		('a padded transporter name', 'freight_loads_transporter_name_length', false, '{"transporter_name":" VRL"}'),
		('a vehicle type of ship', 'freight_loads_vehicle_type_check', false, '{"vehicle_type":"ship"}'),
		('a lower-case vehicle number', 'freight_loads_vehicle_number_shape', false, '{"vehicle_number":"ka01ab1234"}'),
		('a 12-character container', 'freight_loads_container_number_shape', false, '{"container_number":"MSCU12345678"}'),
		('a capacity of 60,001 kg', 'freight_loads_capacity_range', false, '{"vehicle_capacity_kg":60001}'),
		('an 81-character driver name', 'freight_loads_driver_name_length', false, '{"driver_name":"%LONG81%"}'),
		('a driver phone with letters', 'freight_loads_driver_phone_shape', false, '{"driver_phone":"98000ABC00"}'),
		('a 5-character licence', 'freight_loads_driver_licence_shape', false, '{"driver_licence_number":"KA012"}'),
		('a dock door with a space', 'freight_loads_dock_door_shape', false, '{"dock_door":"D 3"}'),
		('six seals', 'freight_loads_seals_shape', false, '{"seals":["1","2","3","4","5","6"]}'),
		('seals as an object', 'freight_loads_seals_shape', false, '{"seals":{"a":1}}'),
		('a dispatched load without a vehicle', 'freight_loads_dispatched_pairing', true, '{"vehicle_number":null}'),
		('a dispatched load without its warehouse party', 'freight_loads_dispatched_pairing', true, '{"warehouse_snapshot":null}'),
		('a handheld dispatch without a device', 'freight_loads_dispatch_source', true, '{"dispatch_source":"handheld"}'),
		('a web dispatch with a device', 'freight_loads_dispatch_source', true, '{"dispatch_device_id":"%R%"}'),
		('101 orders', 'freight_loads_counts_range', true, '{"dispatched_order_count":101}'),
		('20,001 packages', 'freight_loads_counts_range', true, '{"package_count":20001}'),
		('a gross over 20,000 t', 'freight_loads_counts_range', true, '{"gross_weight_grams":20000000001}'),
		('a cancelled load without a reason', 'freight_loads_cancel_pairing', false, '{"status":"cancelled","cancelled_at":"2026-10-30T10:00:00Z","cancelled_by":"%U%"}'),
		('a 201-character cancel reason', 'freight_loads_cancel_pairing', false, '{"status":"cancelled","cancelled_at":"2026-10-30T10:00:00Z","cancelled_by":"%U%","cancel_reason":"%LONG201%"}'),
		('Part B without its confirmer', 'freight_loads_part_b_pairing', false, '{"eway_part_b_confirmed_at":"2026-10-30T10:00:00Z"}'),
		('an empty note', 'freight_loads_note_length', false, '{"note":""}')
	) AS p(name, expected, departed, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || CASE WHEN probe.departed THEN disp ELSE '{}'::jsonb END || jsonb_build_object('id', gen_random_uuid())
				|| replace(replace(replace(replace(probe.override, '%U%', u::text), '%R%', gen_random_uuid()::text), '%LONG81%', repeat('x', 81)), '%LONG201%', repeat('x', 201))::jsonb;
			INSERT INTO "freight_loads" SELECT (jsonb_populate_record(NULL::"freight_loads", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0119' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0119: load probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "freight_loads" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0119: a load probe row survived.';
	END IF;
END $$;
