DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	o uuid;
	base jsonb;
	disp jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'load_id', gen_random_uuid(), 'client_id', gen_random_uuid(),
		'status', 'planned', 'stop_seq', 1,
		'lr_number', NULL, 'lr_date', NULL, 'freight_terms', NULL, 'lr_recorded_at', NULL, 'lr_recorded_by', NULL,
		'removed_at', NULL, 'removed_by', NULL, 'remove_reason', NULL,
		'dispatched_at', NULL, 'package_count', NULL, 'pallet_count', NULL, 'loaded_package_count', NULL, 'weight_grams', NULL,
		'load_exception', NULL, 'compliance_exception', NULL, 'client_snapshot', NULL, 'carriage_snapshot', NULL,
		'delivery_outcome', NULL, 'delivered_at', NULL, 'receiver_name', NULL, 'short_package_count', NULL, 'damaged_package_count', NULL,
		'delivery_note', NULL, 'delivery_seq', 0, 'delivery_recorded_at', NULL, 'delivery_recorded_by', NULL,
		'added_by', u, 'created_at', now(), 'updated_at', now());
	disp := jsonb_build_object(
		'status', 'dispatched', 'dispatched_at', '2026-10-30T10:00:00Z', 'package_count', 15, 'pallet_count', 15,
		'loaded_package_count', 15, 'weight_grams', 9840000,
		'client_snapshot', '{"v":1,"code":"ACME"}'::jsonb, 'carriage_snapshot', '{"v":1,"loadCode":"LD-0001"}'::jsonb,
		'lr_number', '4410', 'lr_date', '2026-10-30', 'freight_terms', 'paid', 'lr_recorded_at', '2026-10-30T10:00:00Z', 'lr_recorded_by', u);
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a planned consignment', false, '{}'),
