			('a removed consignment', false, '{"status":"removed","removed_at":"2026-10-30T10:00:00Z","removed_by":"%U%","remove_reason":"Left on the dock at departure"}'),
			('a dispatched consignment', true, '{}'),
			('a dispatched, unweighed, partly scanned, flagged consignment', true, '{"weight_grams":null,"loaded_package_count":5,"load_exception":"packages-unscanned","compliance_exception":"consignment-documents-missing","lr_number":null,"lr_date":null,"freight_terms":null,"lr_recorded_at":null,"lr_recorded_by":null}'),
			('a consignment the device did not list', true, '{"load_exception":"not-on-device-list","loaded_package_count":0}'),
			('delivered', true, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","receiver_name":"A. Kumar","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
			('delivered with exceptions, amended to version 99', true, '{"delivery_outcome":"delivered-with-exceptions","delivered_at":"2026-11-02T11:20:00Z","damaged_package_count":1,"short_package_count":0,"delivery_note":"pallet 4 crushed corner","delivery_seq":99,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
			('refused', true, '{"delivery_outcome":"refused","delivered_at":"2026-11-02T11:20:00Z","delivery_note":"wrong item","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}')
		) AS s(name, departed, override) LOOP
			rec := base || CASE WHEN shape.departed THEN disp ELSE '{}'::jsonb END
				|| jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid())
