		('a load exception on a planned consignment', 'freight_consignments_load_exception_check', false, '{"load_exception":"packages-unscanned"}'),
		('an unknown load exception', 'freight_consignments_load_exception_check', true, '{"load_exception":"fell-off"}'),
		('an unknown compliance exception', 'freight_consignments_compliance_exception_check', true, '{"compliance_exception":"paperwork-missing"}'),
		('a carriage snapshot v2', 'freight_consignments_snapshots_shape', true, '{"carriage_snapshot":{"v":2}}'),
		('a client snapshot as an array', 'freight_consignments_snapshots_shape', true, '{"client_snapshot":[1]}'),
		('a delivery on a planned consignment', 'freight_consignments_delivery_pairing', false, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('a delivery without its sequence', 'freight_consignments_delivery_pairing', true, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('delivery version 100', 'freight_consignments_delivery_pairing', true, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","delivery_seq":100,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('refused without a note', 'freight_consignments_delivery_outcome_check', true, '{"delivery_outcome":"refused","delivered_at":"2026-11-02T11:20:00Z","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('delivered with a damaged count', 'freight_consignments_delivery_outcome_check', true, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","damaged_package_count":1,"delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('an unknown outcome', 'freight_consignments_delivery_outcome_check', true, '{"delivery_outcome":"lost","delivered_at":"2026-11-02T11:20:00Z","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('damaged 3 of 2 packages', 'freight_consignments_delivery_counts', true, '{"package_count":2,"pallet_count":2,"loaded_package_count":2,"delivery_outcome":"delivered-with-exceptions","delivered_at":"2026-11-02T11:20:00Z","damaged_package_count":3,"delivery_note":"crushed","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('a negative short count', 'freight_consignments_delivery_counts', true, '{"delivery_outcome":"delivered-with-exceptions","delivered_at":"2026-11-02T11:20:00Z","short_package_count":-1,"delivery_note":"x","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}'),
		('a 101-character receiver', 'freight_consignments_delivery_text_length', true, '{"delivery_outcome":"delivered","delivered_at":"2026-11-02T11:20:00Z","receiver_name":"%LONG101%","delivery_seq":1,"delivery_recorded_at":"2026-11-02T12:00:00Z","delivery_recorded_by":"%U%"}')
	) AS p(name, expected, departed, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || CASE WHEN probe.departed THEN disp ELSE '{}'::jsonb END || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid())
				|| replace(replace(probe.override, '%U%', u::text), '%LONG101%', repeat('x', 101))::jsonb;
			INSERT INTO "freight_consignments" SELECT (jsonb_populate_record(NULL::"freight_consignments", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0119' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0119: consignment probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- One live consignment per order: a second live one is refused; a removed one is not counted.
	BEGIN
		o := gen_random_uuid();
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'status', 'removed', 'removed_at', now(), 'removed_by', u, 'remove_reason', 'Order cancelled');
		INSERT INTO "freight_consignments" SELECT (jsonb_populate_record(NULL::"freight_consignments", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o);
		INSERT INTO "freight_consignments" SELECT (jsonb_populate_record(NULL::"freight_consignments", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'load_id', gen_random_uuid());
		INSERT INTO "freight_consignments" SELECT (jsonb_populate_record(NULL::"freight_consignments", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'two live consignments landed';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'freight_consignments_order_live_unique' THEN
				RAISE EXCEPTION 'migration 0119: a second live consignment was refused by % (expected freight_consignments_order_live_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0119' THEN
			RAISE EXCEPTION 'migration 0119: two live consignments of one order were accepted.';
	END;
	IF EXISTS (SELECT 1 FROM "freight_consignments" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0119: a consignment probe row survived.';
	END IF;
END $$;
--> statement-breakpoint
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	-- freight_load_scans
	base := jsonb_build_object(
		'tenant_id', t, 'load_id', gen_random_uuid(), 'consignment_id', c, 'order_id', gen_random_uuid(),
		'package_code', 'O0123456789ABCDEF.1.3', 'pack_seq', 1, 'package_seq', 3, 'status', 'loaded',
		'scanned_at', now(), 'scanned_by', u, 'source', 'web', 'device_id', NULL, 'after_departure', false,
		'unloaded_at', NULL, 'unloaded_by', NULL, 'unload_reason', NULL, 'created_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a loaded web scan', '{}'),
			('an unloaded scan of the same package', '{"status":"unloaded","unloaded_at":"2026-10-30T10:00:00Z","unloaded_by":"%U%","unload_reason":"Removed from the load"}'),
			('a handheld scan synced after the departure, pack 99 package 200', '{"package_code":"O0123456789ABCDEF.99.200","pack_seq":99,"package_seq":200,"source":"handheld","device_id":"%R%","after_departure":true}')
		) AS s(name, override) LOOP
			rec := base || jsonb_build_object('id', gen_random_uuid()) || replace(replace(shape.override, '%U%', u::text), '%R%', gen_random_uuid()::text)::jsonb;
			INSERT INTO "freight_load_scans" SELECT (jsonb_populate_record(NULL::"freight_load_scans", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0119: an accepted scan shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0119' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('a code whose pack disagrees', 'freight_load_scans_code_derived', '{"pack_seq":2}'),
		('a code whose package disagrees', 'freight_load_scans_code_derived', '{"package_seq":4}'),
		('a malformed code (the derived check, never a cast error)', 'freight_load_scans_code_derived', '{"package_code":"O0123456789ABCDEF.x.3"}'),
		('status lost', 'freight_load_scans_status_check', '{"status":"lost"}'),
		('a handheld scan without a device', 'freight_load_scans_source_pairing', '{"source":"handheld"}'),
		('an unloaded scan without a reason', 'freight_load_scans_unloaded_pairing', '{"status":"unloaded","unloaded_at":"2026-10-30T10:00:00Z","unloaded_by":"%U%"}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'consignment_id', gen_random_uuid()) || replace(probe.override, '%U%', u::text)::jsonb;
			INSERT INTO "freight_load_scans" SELECT (jsonb_populate_record(NULL::"freight_load_scans", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0119' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0119: scan probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- One loaded row per (consignment, code).
	BEGIN
		rec := base || jsonb_build_object('id', gen_random_uuid());
		INSERT INTO "freight_load_scans" SELECT (jsonb_populate_record(NULL::"freight_load_scans", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'source', 'handheld', 'device_id', gen_random_uuid());
		INSERT INTO "freight_load_scans" SELECT (jsonb_populate_record(NULL::"freight_load_scans", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'two loaded rows landed';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'freight_load_scans_loaded_unique' THEN
				RAISE EXCEPTION 'migration 0119: a second loaded row was refused by % (expected freight_load_scans_loaded_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0119' THEN
			RAISE EXCEPTION 'migration 0119: one package was loaded twice on one consignment.';
	END;
	IF EXISTS (SELECT 1 FROM "freight_load_scans" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0119: a scan probe row survived.';
	END IF;
END $$;
--> statement-breakpoint
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	l uuid := gen_random_uuid();
	o uuid;
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	-- order_cartons: the package type.
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'client_id', gen_random_uuid(),
		'pack_id', gen_random_uuid(), 'pack_seq', 1, 'seq', 1,
		'weight_grams', 3200, 'length_mm', NULL, 'width_mm', NULL, 'height_mm', NULL,
		'unit_count', 10000, 'line_count', 1, 'handover_id', NULL, 'handover_scanned_at', NULL,
		'package_type', 'carton', 'inner_count', NULL, 'created_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a pallet of 2,500 kg with an inner count', '{"package_type":"pallet","weight_grams":2500000,"inner_count":600}'),
			('a pallet of 3,000 kg without an inner count', '{"package_type":"pallet","weight_grams":3000000}'),
			('a carton of 1,000 kg, unchanged', '{"weight_grams":1000000}')
		) AS s(name, override) LOOP
			o := gen_random_uuid();
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'pack_id', gen_random_uuid(),
				'code', 'O' || upper(right(replace(o::text, '-', ''), 16)) || '.1.1') || shape.override::jsonb;
			INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0119: an accepted package shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0119' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('an inner count on a carton', 'order_cartons_inner_count', '{"inner_count":12}'),
		('a pallet of 10,000 cartons', 'order_cartons_inner_count', '{"package_type":"pallet","inner_count":10000}'),
		('a carton of 1,200 kg', 'order_cartons_weight_range', '{"weight_grams":1200000}'),
		('a pallet of 3,100 kg', 'order_cartons_weight_range', '{"package_type":"pallet","weight_grams":3100000}'),
		('a crate', 'order_cartons_package_type_check', '{"package_type":"crate"}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			o := gen_random_uuid();
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'pack_id', gen_random_uuid(),
				'code', 'O' || upper(right(replace(o::text, '-', ''), 16)) || '.1.1') || probe.override::jsonb;
			INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0119' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0119: package probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- attachments: a loading-sheet page on a freight load; an LR scan on an order.
	base := jsonb_build_object(
		'tenant_id', t, 'client_id', NULL, 'warehouse_id', gen_random_uuid(),
		'purpose', 'loading-sheet', 'doc_kind', NULL, 'status', 'attached', 'source', 'web',
		'owner_type', 'freight_load', 'owner_id', l, 'owner_parent_id', l,
		'client_ref', NULL, 'upload_key', NULL, 'upload_hash', repeat('b', 64), 'raw_sha256', repeat('c', 64),
		'content_type', 'image/jpeg', 'byte_size', 1000, 'sha256', repeat('a', 64), 'width', 1600, 'height', 1200,
		'page_count', NULL, 'captured_at', NULL, 'uploaded_at', now(), 'device_id', NULL, 'created_by', u,
		'removed_by', NULL, 'removed_at', NULL, 'removed_reason', NULL, 'purged_at', NULL,
		'created_at', now(), 'updated_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a loading-sheet page on a freight load', '{}'),
			('a staged loading-sheet photo', '{"status":"staged","source":"handheld","device_id":"%R%","warehouse_id":null,"owner_type":null,"owner_id":null,"owner_parent_id":null,"client_ref":"01JZ0000000000000000000119"}'),
			('a scanned LR on an order', '{"purpose":"shipping-document","doc_kind":"lr","client_id":"%R%","owner_type":"order"}')
		) AS s(name, override) LOOP
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'object_key', 'tenants/probe/attachments/' || gen_random_uuid())
				|| replace(shape.override, '%R%', gen_random_uuid()::text)::jsonb;
			INSERT INTO "attachments" SELECT (jsonb_populate_record(NULL::"attachments", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0119: an accepted attachment shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0119' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('a loading sheet on an order', 'attachments_purpose_owner', '{"owner_type":"order"}'),
		('a handover sheet on a freight load', 'attachments_purpose_owner', '{"purpose":"handover-sheet"}'),
		('an unknown owner type', 'attachments_owner_type_check', '{"owner_type":"vehicle"}'),
		('an unknown document kind', 'attachments_doc_kind_check', '{"purpose":"shipping-document","doc_kind":"gate-pass","owner_type":"order"}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'object_key', 'tenants/probe/attachments/' || gen_random_uuid()) || probe.override::jsonb;
			INSERT INTO "attachments" SELECT (jsonb_populate_record(NULL::"attachments", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0119' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0119: attachment probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- mail, contacts, webhooks.
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
		VALUES (gen_random_uuid(), t, 'client-delivery-update', 'a@example.in', '{}', 'pending', now(), u, 'client-delivery-update:c1:1:a@example.in', 1);
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles","email_events")
		VALUES (gen_random_uuid(), t, u, 'Asha', 'asha@example.in', '{}', ARRAY['order.dispatched', 'delivery.recorded']);
		INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","secret_sealed","secret_hint","consecutive_failures","rate_window_count","created_by")
		VALUES (gen_random_uuid(), t, u, 'https://hooks.acme.in/wms', ARRAY['order.dispatched', 'order.delivered'], 'active', 'v1:x', 'abcd', 0, 0, u);
		INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body")
		VALUES (gen_random_uuid(), t, u, 'order.delivered', gen_random_uuid(), '{}');
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0119: an accepted mail, contact or webhook shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0119' THEN
			NULL;
	END;
	refused_by := NULL;
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority")
		VALUES (gen_random_uuid(), t, 'client-delivery-update', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 1);
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0119' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'email_messages_client_shape_check' THEN
		RAISE EXCEPTION 'migration 0119: a delivery update without a client was refused by % (expected email_messages_client_shape_check).', coalesce(refused_by, 'nothing');
	END IF;
	refused_by := NULL;
	BEGIN
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles","email_events")
		VALUES (gen_random_uuid(), t, u, 'Asha', 'asha2@example.in', '{}', ARRAY['delivery.recorded', 'delivery.recorded']);
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0119' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'client_contacts_email_events_check' THEN
		RAISE EXCEPTION 'migration 0119: a duplicate delivery event was refused by % (expected client_contacts_email_events_check).', coalesce(refused_by, 'nothing');
	END IF;
	refused_by := NULL;
	BEGIN
		INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","secret_sealed","secret_hint","consecutive_failures","rate_window_count","created_by")
		VALUES (gen_random_uuid(), t, u, 'https://hooks.acme.in/wms2', ARRAY['order.delivered', 'order.delivered'], 'active', 'v1:x', 'abcd', 0, 0, u);
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0119' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'webhook_endpoints_event_types_check' THEN
		RAISE EXCEPTION 'migration 0119: a duplicate order.delivered was refused by % (expected webhook_endpoints_event_types_check).', coalesce(refused_by, 'nothing');
	END IF;
	refused_by := NULL;
	BEGIN
		INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body")
		VALUES (gen_random_uuid(), t, u, 'order.returned', gen_random_uuid(), '{}');
		RAISE EXCEPTION USING ERRCODE = 'P0119', MESSAGE = 'a refused probe landed';
	EXCEPTION
		WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		WHEN SQLSTATE 'P0119' THEN
			refused_by := NULL;
	END;
	IF refused_by IS DISTINCT FROM 'webhook_events_type_check' THEN
		RAISE EXCEPTION 'migration 0119: an unknown webhook event was refused by % (expected webhook_events_type_check).', coalesce(refused_by, 'nothing');
	END IF;
	IF EXISTS (SELECT 1 FROM "order_cartons" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "attachments" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "client_contacts" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "webhook_endpoints" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "webhook_events" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0119: a probe row survived.';
	END IF;
END $$;
